1	export type Item = {
2	  type: string;
3	};
4	
5	export type Step = {
6	  op: string;
7	  items: Item[];
8	};
9	
10	export type Customer = {
11	  yearsWithMHPCO: number;
12	};
13	
14	export type Scenario = {
15	  customer: Customer;
16	  steps: Step[];
17	};
18	
19	export type QuoteResult = {
20	  premium: number;
21	};
22	
23	export type ScenarioOutcome = {
24	  results: QuoteResult[];
25	};
26	
27	const PROCESSING_FEE = 5;
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const FIRST_INSURANCE_PERCENT = 10;
39	
40	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
41	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
42	// intermediates to stay exact, so every percentage goes through here.
43	const PERCENT_WHOLE = 100;
44	
45	const percentOf = (amount: number, percent: number): number =>
46	  (amount * percent) / PERCENT_WHOLE;
47	
48	// Rounding always favours MHPCO: premiums round up, payouts round down.
49	const roundPremium = (amount: number): number => Math.ceil(amount);
50	
51	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	// The policy base premium is the sum of every insured item's base premium.
54	const policyBasePremiumOf = (items: Item[]): number =>
55	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
56	
57	const quoteStep = (step: Step): QuoteResult => {
58	  const basePremium = policyBasePremiumOf(step.items);
59	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
60	
61	  return {
62	    premium: roundPremium(
63	      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
64	    ),
65	  };
66	};
67	
68	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
69	  results: scenario.steps.map(quoteStep),
70	});
